import {api,mode} from './api.js';
import {money,num,date,stamp,esc,calculate,progress,PROC_STATES,QUESTION_STATES,CONTRACT_STATES,paymentLabels,sumMoney} from './model.js';

const supplierMode=document.documentElement.dataset.mode==='supplier';
const root=document.querySelector('#app');
const views=supplierMode?[
 ['overview','Обзор'],['offers','Предложения'],['incoming','Запросы'],['promotion','Продвижение'],['settings','Настройки']
]:[['overview','Главная'],['purchases','Закупки'],['needs','Потребности'],['questions','Вопросы'],['contracts','Контракты'],['payments','Платежи'],['settings','Настройки']];
let data=null,route=location.hash.slice(1).split('?')[0]||'overview',selectedQuestion=null,selectedContract=null,selectedPurchase=null,filter='all',search='',showNotifs=false,dialog=null,toastTimer=null;
if(!views.some(x=>x[0]===route))route='overview';
const icon=(name)=>{
 const d={
 arrow:'M4 12h15m-6-6 6 6-6 6',back:'M20 12H5m6-6-6 6 6 6',chev:'m6 9 6 6 6-6',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 8-3 9h18c0-1-3-2-3-9M10 21h4',
 plus:'M12 4v16M4 12h16',x:'M5 5l14 14M19 5 5 19',check:'m4 12 5 5L20 6',search:'M11 19a8 8 0 1 0 0-16 8 8 0 0 0 0 16Zm6-2 5 5',
 more:'M5 12h.01M12 12h.01M19 12h.01',down:'m6 9 6 6 6-6',next:'m9 18 6-6-6-6',file:'M5 3h9l5 5v13H5zM14 3v6h5M8 13h8M8 17h6',send:'M3 11 21 3l-8 18-3-8-7-2ZM10 13l11-10',
 box:'M12 3 2.5 8l9.5 5 9.5-5-9.5-5ZM2.5 8v10l9.5 5 9.5-5V8M12 13v10',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18Zm0 5v5l4 2',
 wallet:'M3 6h18v14H3zM3 6l4-3h12M16 11h5v5h-5a2.5 2.5 0 0 1 0-5Z',shield:'m12 2 9 4v6c0 6-4 9-9 11-5-2-9-5-9-11V6l9-4Zm-4 10 3 3 5-6',
 setting:'M12 2v4m0 12v4M2 12h4m12 0h4M4.9 4.9l2.9 2.9m8.4 8.4 2.9 2.9m0-14.2-2.9 2.9m-8.4 8.4-2.9 2.9M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8Z',
 home:'M3 10.5 12 3l9 7.5V21h-7v-6h-4v6H3z',question:'M12 21a9 9 0 1 0 0-18 9 9 0 0 0 0 18Zm-3-11a3 3 0 1 1 5 2c-2 1-2 2-2 3m0 3h.01',
 calendar:'M4 6h16v15H4zM8 3v6m8-6v6M4 11h16',download:'M12 3v13m-5-5 5 5 5-5M4 18v3h16v-3',user:'M12 12a4 4 0 1 0 0-8 4 4 0 0 0 0 8Zm-8 9a8 8 0 0 1 16 0',
 info:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18Zm0 8v5m0-8h.01',spark:'m12 2 2.6 6.8L22 12l-7.4 3.2L12 22l-2.6-6.8L2 12l7.4-3.2L12 2Z'
 };return `<svg class="glyph" viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><path d="${d[name]||d.info}"/></svg>`;
};
const button=(text,act,cls='primary',attrs='')=>`<button class="btn ${cls}" data-action="${act}" ${attrs}>${text}</button>`;
const status=(key,dict)=>{const [name,tone]=dict[key]||['Неизвестно','neutral'];return `<span class="status ${tone}"><i></i>${esc(name)}</span>`};
const infoBox=(title,body)=>`<div class="note-box">${icon('info')}<div><strong>${title}</strong><p>${body}</p></div></div>`;
const sectionHead=(eyebrow,title,subtitle,side='')=>`<div class="section-head"><div><span class="eyebrow">${eyebrow}</span><h1>${title}</h1>${subtitle?`<p>${subtitle}</p>`:''}</div>${side?`<div class="head-side">${side}</div>`:''}</div>`;
const purchase=id=>data.purchases.find(p=>p.id===id);
const procurementValue=p=>calculate(p,p.quantity).groupKop;
const moneyTotal=ps=>ps.reduce((n,p)=>n+procurementValue(p),0);
function navigate(view){route=view;location.hash=view;filter='all';search='';selectedPurchase=null;dialog=null;showNotifs=false;render();window.scrollTo({top:0,behavior:'auto'});}
function toast(message,type='ok'){let n=document.querySelector('.toast');if(!n){n=document.createElement('div');n.className='toast';document.body.append(n);}n.innerHTML=`<span class="toast-mark">${icon(type==='err'?'x':'check')}</span>${esc(message)}`;n.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>n.classList.remove('visible'),4600);}
async function mutate(method,...args){try{data=await api[method](...args);dialog=null;render();toast(method==='answerQuestion'?'Ответ сохранён. Предварительное согласование не меняет контракт.':method==='confirmContract'?'Условия подтверждены в деморежиме. Юридическая подпись не создана.':method==='createNeed'?'Потребность добавлена':method==='createOffer'?'Предложение опубликовано':'Изменения сохранены');}catch(e){toast(e.message||'Операция не выполнена','err')}}
function brand(){return `<span class="symbol" aria-hidden="true"><span></span><span></span><span></span></span><span class="wordmark">оптима<span>.</span></span>`;}
function navLinks(){return views.map(([id,label],i)=>{const count=id==='questions'?data.questions.filter(q=>q.status==='pending').length:id==='contracts'?data.contracts.filter(c=>c.status==='review').length:0;return `<button class="nav-link ${route===id?'active':''}" data-action="route" data-route="${id}" aria-current="${route===id?'page':'false'}"><span class="nav-numeral">0${i+1}</span><span>${label}</span>${count?`<em>${count}</em>`:''}</button>`}).join('');}
function shell(){const notifCount=data.notifications.filter(x=>x.unread).length;
 root.innerHTML=`<div class="app-layout"><aside class="side"><a class="side-brand" href="#overview" aria-label="Оптима. На главную">${brand()}<small>${supplierMode?'для поставщиков':'для бизнеса'}</small></a><div class="side-context">${supplierMode?'КАБИНЕТ ПОСТАВЩИКА':'РАБОЧИЙ КАБИНЕТ'}<strong>${supplierMode?'ПакетПро':esc(data.company.name)}</strong></div><nav class="nav-list" aria-label="Основные разделы">${navLinks()}</nav><div class="side-bottom"><div class="rail-online"><i></i> Демонстрационный режим</div><div>Совместные закупки<br>под контролем</div><small>CONCEPT / 2026</small></div></aside>
 <div class="main-area"><header class="topbar"><div class="mobile-brand">${brand()}</div><div class="crumb">${supplierMode?'Поставщик':'Компания'} <span>/</span> <b>${esc(views.find(v=>v[0]===route)?.[1]||'Главная')}</b></div><div class="top-actions"><span class="demo-label">DEMO · 2026</span>${supplierMode?`<a class="mode-switch" href="../workspace/">Кабинет покупателя ${icon('arrow')}</a>`:`<a class="mode-switch" href="../supplier/">Поставщикам ${icon('arrow')}</a>`}<div class="notification-wrap"><button class="icon-btn ${showNotifs?'pressed':''}" data-action="notifications" aria-label="Уведомления${notifCount?`, ${notifCount} непрочитанных`:''}" aria-expanded="${showNotifs}">${icon('bell')}${notifCount?'<i class="notif-dot"></i>':''}</button>${showNotifs?notifs():''}</div><button class="account" data-action="route" data-route="settings" aria-label="Настройки компании"><span>АС</span><div><b>${supplierMode?'ПакетПро':esc(data.company.name)}</b><small>Администратор</small></div>${icon('chev')}</button></div></header><main id="main" class="page" tabindex="-1">${supplierMode?renderSupplier():renderBuyer()}</main><footer class="app-footer"><span>© Оптима · Концепт для финтех-хакатона</span><span>Без реальных банковских подключений, подписей и платежей</span></footer></div>
 ${!supplierMode?`<nav class="bottom-tabs" aria-label="Мобильная навигация">${views.filter(([id])=>['overview','purchases','questions','contracts'].includes(id)).map(([id,label])=>`<button class="${route===id?'active':''}" data-action="route" data-route="${id}">${icon({overview:'home',purchases:'box',questions:'question',contracts:'file'}[id])}<span>${label}</span></button>`).join('')}<button class="${['payments','settings'].includes(route)?'active':''}" data-action="route" data-route="payments">${icon('more')}<span>Ещё</span></button></nav>`:''}
 </div>${dialog?dialogView():''}`;
}
function notifs(){return `<div class="notif-panel" role="region" aria-label="Уведомления"><div class="notif-head"><strong>Уведомления</strong><button data-action="readAll">Отметить прочитанным</button></div>${data.notifications.slice(0,6).map(n=>`<button class="notif-item ${n.unread?'unread':''}" data-action="openNotif" data-id="${esc(n.id)}" data-target="${esc(n.target)}"><span>${esc(n.title)}</span><small>${esc(n.description)}</small></button>`).join('')}</div>`}
function renderBuyer(){return ({overview:overviewView,purchases:purchasesView,needs:needsView,questions:questionsView,contracts:contractsView,payments:paymentsView,settings:settingsView}[route]||overviewView)();}
function coloredArrow(){return `<span class="round-arrow">${icon('arrow')}</span>`;}
function taskRow(kind,obj){const isQ=kind==='question',p=purchase(obj.purchaseId);return `<button class="task-row" data-action="task" data-kind="${kind}" data-id="${esc(obj.id)}"><span class="task-kind ${isQ?'kind-question':'kind-contract'}">${isQ?'ВОПРОС':'КОНТРАКТ'}</span><div><strong>${esc(obj.title)}</strong><small>${esc(p?.title||'Закупка')} · ${esc(isQ?obj.from:obj.supplier)}</small></div><span class="task-date">${stamp(obj.created)}</span>${coloredArrow()}</button>`;}
function overviewView(){const active=data.purchases.filter(p=>p.status!=='delivered'),questions=data.questions.filter(q=>q.status==='pending'),contracts=data.contracts.filter(c=>c.status==='review'),tasks=[...questions.map(x=>({kind:'question',v:x})),...contracts.map(x=>({kind:'contract',v:x}))];
 return `<div class="overview"><div class="overline">17 ОКТЯБРЯ 2026 <span class="overline-rule"></span> БИЗНЕС-КАБИНЕТ</div><div class="welcome"><div><h1>Добрый вечер,<br><em>${esc(data.company.contact.split(' ')[0])}.</em></h1><p>Закупки движутся. Есть ${tasks.length} ${tasks.length===1?'действие':'действия'}, которые требуют вашего решения.</p></div><div class="welcome-marker" aria-hidden="true"><span>О</span><small>PTIMA / B2B</small></div></div>
 <div class="metric-band"><div><span>В РАБОТЕ</span><strong>${String(active.length).padStart(2,'0')}</strong><small>совместных закупки</small></div><div><span>ВАШ ОБЪЁМ ЗАКАЗОВ</span><strong>${money(moneyTotal(active))}</strong><small>по демоценам с доставкой</small></div><div><span>НУЖНО РЕШИТЬ</span><strong>${String(tasks.length).padStart(2,'0')}</strong><small>вопросы и контракты</small></div></div>
 <div class="content-columns"><section class="primary-column"><div class="heading-row"><div><span class="eyebrow">01 / В ФОКУСЕ</span><h2>Требуют решения</h2></div><span class="subtle">Сначала самое важное</span></div><div class="task-list">${tasks.length?tasks.slice(0,4).map(t=>taskRow(t.kind,t.v)).join(''):`<div class="empty">Сейчас нет действий, требующих ответа.</div>`}</div>
 <div class="heading-row space-top"><div><span class="eyebrow">02 / ВАШИ ЗАКУПКИ</span><h2>В работе</h2></div><button class="text-link" data-action="route" data-route="purchases">Все закупки ${icon('arrow')}</button></div><div class="compact-purchases">${active.slice(0,3).map(p=>purchaseRow(p,true)).join('')}</div></section>
 <aside class="secondary-column"><div class="editorial-panel"><span class="eyebrow">СЛЕДУЮЩЕЕ СОБЫТИЕ</span><span class="editorial-date">20<span>окт</span></span><strong>Поставка перчаток</strong><p>ПрофСнаб · 30 уп.<br>Готовится к исполнению</p><button data-action="showPurchase" data-id="PR-2404">Открыть закупку ${icon('arrow')}</button><span class="editorial-number">01 / 04</span></div><div class="side-activity"><span class="eyebrow">ПОСЛЕДНИЕ СОБЫТИЯ</span>${data.activity.slice(0,3).map(x=>`<div><i></i><strong>${esc(x.verb)}</strong><small>${esc(x.details)}</small></div>`).join('')}</div></aside></div></div>`;
}
function qtyProgress(p){return `<div class="qty-progress"><div class="progress-label"><strong>${num(p.collectedQty)} / ${num(p.thresholdQty)} ${esc(p.unit)}</strong><span>${progress(p)}%</span></div><div class="meter" role="progressbar" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${progress(p)}" aria-label="Собранный объём"><i style="width:${progress(p)}%"></i></div></div>`;}
function purchaseRow(p,compact=false){return `<button class="purchase-row ${compact?'compact':''}" data-action="showPurchase" data-id="${esc(p.id)}"><span class="purchase-monogram ${esc(p.icon)}" aria-hidden="true">${{water:'19',paper:'A4',parcel:'P',gloves:'M'}[p.icon]||'•'}</span><span class="purchase-name"><strong>${esc(p.title)}</strong><small>${esc(p.supplier)} · ${num(p.quantity)} ${esc(p.unit)}</small></span>${compact?'<span class="purchase-compact-status">'+status(p.status,PROC_STATES)+'</span>':`<span class="purchase-table-status">${status(p.status,PROC_STATES)}</span><span class="purchase-table-qty">${qtyProgress(p)}</span><span class="purchase-table-price"><strong>${money(procurementValue(p))}</strong><small>Доставка: ${date(p.delivery)}</small></span>`}${coloredArrow()}</button>`}
function purchasesView(){const set=data.purchases.filter(p=>filter==='all'||(filter==='active'?p.status!=='delivered':p.status==='delivered')).filter(p=>(p.title+' '+p.supplier+' '+p.id).toLocaleLowerCase('ru').includes(search.toLocaleLowerCase('ru')));
 return `${sectionHead('01 / ВАШИ ЗАКУПКИ','Закупки','Каждая закупка — самостоятельный заказ. Общий объём влияет на цену.',`<button class="btn outline" data-action="route" data-route="questions">${icon('question')} Вопросы по закупкам</button>`)}<div class="filter-line"><div class="tabset">${[['all','Все'],['active','В работе'],['done','Завершённые']].map(([id,t])=>`<button class="${filter===id?'active':''}" data-action="filter" data-filter="${id}">${t}</button>`).join('')}</div><label class="search-box">${icon('search')}<input id="filter-search" placeholder="Закупка, поставщик" value="${esc(search)}" autocomplete="off" aria-label="Поиск закупки"></label></div><div class="purchase-table"><div class="table-labels"><span>ЗАКУПКА</span><span>СТАТУС</span><span>ОБЩИЙ ОБЪЁМ</span><span>ВАШ ЗАКАЗ</span><span></span></div>${set.length?set.map(p=>purchaseRow(p)).join(''):'<div class="empty">Закупки не найдены. Попробуйте изменить фильтр.</div>'}</div><div class="table-caption">* Все суммы и статусы демонстрационные. Заказы и документы в разных компаниях не объединяются.</div>`;
}
function needsView(){return `${sectionHead('02 / ПОТРЕБНОСТИ КОМПАНИИ','Потребности','Формируйте собственный список спроса и готовьтесь к объединению закупок.',`<button class="btn primary" data-action="newNeed">${icon('plus')} Добавить товар</button>`)}<div class="needs-table"><div class="needs-labels"><span>НАИМЕНОВАНИЕ</span><span>ОБЪЁМ</span><span>СРОК</span><span>СОСТОЯНИЕ</span></div>${data.needs.map(n=>`<div class="needs-row"><div><strong>${esc(n.title)}</strong><small>${esc(n.id)}</small></div><strong>${num(n.quantity)} ${esc(n.unit)}</strong><span>${date(n.deadline)}</span><span class="needs-status">${n.status==='matched'?'Найдено совпадение':'Поиск предложений'}</span><button class="icon-btn" data-action="deleteNeed" data-id="${esc(n.id)}" aria-label="Удалить ${esc(n.title)}">${icon('x')}</button></div>`).join('')||'<div class="empty">Добавьте первую потребность.</div>'}</div>`}
function questionsView(){const qlist=data.questions.filter(q=>filter==='all'||(filter==='active'?q.status==='pending':q.status!=='pending'));
 selectedQuestion=qlist.some(q=>q.id===selectedQuestion)?selectedQuestion:qlist[0]?.id;const q=data.questions.find(x=>x.id===selectedQuestion),p=q&&purchase(q.purchaseId);
 return `${sectionHead('02 / ПРЕДВАРИТЕЛЬНЫЕ СОГЛАСОВАНИЯ','Вопросы','Здесь можно обсудить изменения. Ответ сам по себе не изменяет контракт.')}${infoBox('Это не юридическое согласие','Ваш ответ здесь — только предварительное решение. Любое изменение условий оформляется отдельным документом в разделе «Контракты».')}<div class="inbox-toolbar"><div class="tabset">${[['all','Все'],['active','Ожидают ответа'],['done','Обработаны']].map(([id,t])=>`<button data-action="filter" data-filter="${id}" class="${filter===id?'active':''}">${t}</button>`).join('')}</div><span class="subtle">${qlist.length} обращения</span></div><div class="inbox-grid"><div class="inbox-list" role="list">${qlist.length?qlist.map(x=>{const pp=purchase(x.purchaseId);return `<button class="inbox-item ${selectedQuestion===x.id?'selected':''}" data-action="selectQuestion" data-id="${esc(x.id)}"><span class="small-overline">${esc(x.from)} · ${stamp(x.created)}</span><strong>${esc(x.title)}</strong><small>${esc(pp?.title||'')}</small>${status(x.status,QUESTION_STATES)}</button>`}).join(''):'<div class="empty">Нет вопросов в этой категории.</div>'}</div><article class="inbox-detail">${q?`<div class="detail-head"><span class="eyebrow">ВОПРОС № ${esc(q.id)}</span>${status(q.status,QUESTION_STATES)}</div><h2>${esc(q.title)}</h2><p class="detail-lead">${esc(q.body)}</p><dl class="detail-facts"><div><dt>Закупка</dt><dd>${esc(p?.title||'—')}</dd></div><div><dt>Поставщик</dt><dd>${esc(q.from)}</dd></div><div><dt>Текущая дата</dt><dd>${date(p?.delivery)}</dd></div>${q.proposedDelivery?`<div><dt>Предлагаемая дата</dt><dd class="fact-accent">${date(q.proposedDelivery)}</dd></div>`:''}</dl>${q.status==='pending'?`<div class="inbox-actions">${button('Предварительно согласовать','acceptQuestion','primary',`data-id="${esc(q.id)}"`)}${button('Отклонить предложение','declineQuestion','outline',`data-id="${esc(q.id)}"`)}</div>`:infoBox('Ответ зафиксирован',q.status==='accepted'?'Создан документ для отдельного подтверждения в «Контрактах».':'Предложение отклонено, текущие условия сохранены.')}`:'<div class="empty">Выберите вопрос слева.</div>'}</article></div>`;
}
function contractsView(){const cs=data.contracts.filter(c=>filter==='all'||(filter==='active'?c.status==='review':c.status!=='review'));
 selectedContract=cs.some(c=>c.id===selectedContract)?selectedContract:cs[0]?.id;
 const c=cs.find(x=>x.id===selectedContract),p=c&&purchase(c.purchaseId);
 return `${sectionHead('03 / ДОКУМЕНТЫ И УСЛОВИЯ','Контракты','Проверяйте финальные параметры перед подтверждением.',`<span class="paper-note">ДЕМО · НЕ ЭЛЕКТРОННАЯ ПОДПИСЬ</span>`)}${infoBox('Юридически значимое подписание не подключено','Подтверждение в этой версии моделирует процесс согласования условий. Для действительной подписи понадобится авторизация подписанта и интеграция с ЭДО/УКЭП.')}
 <div class="inbox-toolbar"><div class="tabset">${[['all','Все документы'],['active','К подтверждению'],['done','История']].map(([id,t])=>`<button data-action="filter" data-filter="${id}" class="${filter===id?'active':''}">${t}</button>`).join('')}</div><span class="subtle">${cs.length} документа</span></div>
 <div class="inbox-grid contract-inbox"><div class="inbox-list">${cs.length?cs.map(x=>`<button class="inbox-item ${selectedContract===x.id?'selected':''}" data-action="selectContract" data-id="${esc(x.id)}"><span class="small-overline">${esc(x.number)} · ВЕРСИЯ ${x.version}</span><strong>${esc(x.title)}</strong><small>${esc(x.supplier)}</small>${status(x.status,CONTRACT_STATES)}</button>`).join(''):'<div class="empty">Документов пока нет.</div>'}</div><article class="inbox-detail contract-detail">${c?`<div class="detail-head"><span class="eyebrow">${esc(c.number)} / V${c.version}</span>${status(c.status,CONTRACT_STATES)}</div><h2>${esc(c.title)}</h2><p class="detail-lead">${esc(c.description)}</p><div class="contract-amount"><small>СУММА ПО УСЛОВИЯМ</small><strong>${money(c.amountKop)}</strong></div><dl class="detail-facts"><div><dt>Поставщик</dt><dd>${esc(c.supplier)}</dd></div><div><dt>Закупка</dt><dd>${esc(p?.title||'—')}</dd></div><div><dt>Дата поставки</dt><dd>${date(c.proposedDelivery||p?.delivery)}</dd></div><div><dt>Тип документа</dt><dd>${c.kind==='change'?'Изменение условий':'Основные условия'}</dd></div><div><dt>Дата подготовки</dt><dd>${date(c.created)}</dd></div></dl><div class="document-preview"><span class="document-corner">01</span><span>OPTIMA / ДОКУМЕНТ</span><strong>${esc(c.number)}</strong><p>Демонстрационный набор условий закупки. Подлинный договор и электронная подпись отсутствуют.</p></div>${c.status==='review'?`<div class="inbox-actions">${button('Проверить и подтвердить','confirmDialog','primary',`data-id="${esc(c.id)}"`)}${button('Отклонить','declineDialog','outline',`data-id="${esc(c.id)}"`)}</div>`:infoBox('Документ обработан',c.status==='confirmed'?'Условия подтверждены в демонстрационной системе.':'Документ отклонён. Действующие условия не менялись.')}`:'<div class="empty">Выберите документ.</div>'}</article></div>`;
}
function paymentsView(){return `${sectionHead('04 / РАСЧЁТЫ ПО ЗАКУПКАМ','Платежи','Только операции, связанные с Optima. Это не история счёта ВТБ.',`<span class="paper-note">БАНКОВСКОЕ API НЕ ПОДКЛЮЧЕНО</span>`)}${infoBox('Граница банковских данных','Здесь показаны исключительно демонстрационные платежи по закупкам Optima. Доступ к переводам компании и банковским счетам потребует отдельного разрешения и интеграции.')}
 <div class="payment-summary"><div><span>ОПЛАЧЕНО ПО ЗАКУПКАМ (ДЕМО)</span><strong>${money(sumMoney(data.payments.filter(p=>p.status==='executed')))}</strong></div><div><span>ЗАПЛАНИРОВАНО</span><strong>${money(sumMoney(data.payments.filter(p=>p.status==='scheduled')))}</strong></div></div><div class="heading-row"><div><span class="eyebrow">ЖУРНАЛ ОПЕРАЦИЙ</span><h2>История по закупкам</h2></div><button class="text-link" data-action="downloadPayments">Выгрузить CSV ${icon('download')}</button></div><div class="payment-list">${data.payments.map(p=>`<div class="payment-row"><span class="payment-icon">${icon('wallet')}</span><div><strong>${esc(p.title)}</strong><small>${esc(p.reference)} · ${stamp(p.date)}</small></div><span>${status(p.status,paymentLabels)}</span><strong>${money(p.sumKop)}</strong></div>`).join('')}</div>`;}
function settingsView(){return `${sectionHead('05 / ПАРАМЕТРЫ','Настройки','Информация о компании и доступе к кабинету.')}${infoBox('Роли и права','В демоверсии доступен один пользователь с правами администратора. На реальном бэкенде понадобятся права сотрудников и подтверждение полномочий на подписание.')}
 <div class="settings-layout"><form id="settings-form" class="form-panel"><span class="eyebrow">ПРОФИЛЬ КОМПАНИИ</span><label>Название организации<input required name="name" minlength="3" value="${esc(data.company.name)}"></label><label>Контактное лицо<input required name="contact" minlength="2" value="${esc(data.company.contact)}"></label><label>Электронная почта<input type="email" name="email" value="${esc(data.company.email)}"></label><div class="form-footer"><button type="submit" class="btn primary">Сохранить изменения</button></div></form><aside class="settings-aside"><div class="large-initials">С</div><strong>${esc(data.company.name)}</strong><span>${esc(data.company.role)}</span><p>ИНН (демо): ${esc(data.company.inn)}</p><div class="settings-separator"></div><span>МОДЕЛЬ РАБОТЫ</span><p>Покупатель · Отдельные договоры · Общий закупочный объём</p><button class="text-link" data-action="resetDialog">Сбросить демоданные ${icon('arrow')}</button></aside></div>`;}
function supplierStat(v,title,sub){return `<div class="supplier-stat"><small>${title}</small><strong>${v}</strong><span>${sub}</span></div>`}
function renderSupplier(){const offers=data.supplierOffers,active=offers.filter(x=>x.published);if(route==='overview')return `${sectionHead('OPTIMA SUPPLY / 01','Работа с предложениями','Видимость спроса, цены и подготовка поставок в одном окне.',`<button data-action="route" data-route="offers" class="btn primary">${icon('plus')} Новое предложение</button>`)}<div class="supplier-masthead"><div><span class="eyebrow">КЛЮЧЕВОЙ ПОКАЗАТЕЛЬ</span><h2>${num(active.reduce((n,x)=>n+x.collectedQty,0))} <small>единиц в запросах</small></h2><p>Совокупный спрос по опубликованным предложениям.</p></div><div class="supplier-masthead-glyph">S<span>↗</span></div></div><div class="supplier-metrics">${supplierStat(String(active.length).padStart(2,'0'),'ОПУБЛИКОВАНО','активных предложений')}${supplierStat(String(active.filter(o=>o.collectedQty>=o.thresholdQty).length).padStart(2,'0'),'ГОТОВЫ К ПАРТИИ','достигли порога')}${supplierStat(String(active.filter(o=>o.promoted).length).padStart(2,'0'),'В ПРОДВИЖЕНИИ','демо-размещения')}</div><div class="heading-row space-top"><div><span class="eyebrow">АКТИВНЫЕ ПОЗИЦИИ</span><h2>Ваш ассортимент</h2></div><button class="text-link" data-action="route" data-route="offers">Все предложения ${icon('arrow')}</button></div>${offerTable(offers.slice(0,3))}`;
 if(route==='offers')return `${sectionHead('OPTIMA SUPPLY / 02','Предложения','Публикуйте оптовые условия и следите за формированием групп.',`<button class="btn primary" data-action="newOffer">${icon('plus')} Добавить предложение</button>`)}${offerTable(offers)}`;
 if(route==='incoming')return `${sectionHead('OPTIMA SUPPLY / 03','Запросы покупателей','Спрос компаний по текущим предложениям. Запросы ниже — демонстрационные.')}${infoBox('Согласования не являются контрактом','Предложения по изменению сроков, количества и способа поставки сначала обсуждаются, а финальные условия подтверждаются отдельно.')}
 <div class="supplier-incomings">${data.purchases.filter(p=>p.supplier==='ПакетПро').slice(0,4).map(p=>`<div class="incoming-row"><div><small>${esc(p.id)} · ${esc(p.supplier)}</small><strong>${esc(p.title)}</strong><span>${num(p.quantity)} ${esc(p.unit)} · Поставка ${date(p.delivery)}</span></div>${status(p.status,PROC_STATES)}</div>`).join('')}</div>`;
 if(route==='promotion')return `${sectionHead('OPTIMA SUPPLY / 04','Продвижение','Дополнительная видимость предложения. Пока только демонстрационный сценарий.')}${infoBox('Платное продвижение не подключено','В демоверсии переключатель меняет маркер продвижения, но не взимает деньги и не изменяет алгоритм соответствия закупок. В будущем такие размещения должны маркироваться как реклама.')}
 <div class="promotion-list">${offers.map(o=>`<div><div><strong>${esc(o.title)}</strong><small>${o.promoted?'Рекламный статус · демо':'Обычное предложение'}</small></div><button class="btn ${o.promoted?'outline':'primary'}" data-action="promote" data-id="${esc(o.id)}">${o.promoted?'Выключить демо':'Тестировать продвижение'}</button></div>`).join('')}</div>`;
 return `${sectionHead('OPTIMA SUPPLY / 05','Профиль поставщика','Контактные данные, настройки уведомлений и права доступа.')}${infoBox('Следующий этап интеграции','В MVP профиль поставщика использует общие демоданные. Для эксплуатации потребуются отдельная авторизация, реквизиты, проверка поставщика и договор оферты.')}`;
}
function offerTable(offers){return `<div class="offer-table"><div class="offer-thead"><span>НАИМЕНОВАНИЕ</span><span>ОБЪЁМ ПАРТИИ</span><span>ОПТОВАЯ ЦЕНА</span><span>ПУБЛИКАЦИЯ</span></div>${offers.map(o=>`<div class="offer-row"><div><strong>${esc(o.title)}</strong><small>${esc(o.category)} · ${esc(o.id)}</small></div><div>${num(o.collectedQty)} / ${num(o.thresholdQty)} ${esc(o.unit)}<div class="meter"><i style="width:${progress(o)}%"></i></div></div><strong>${money(o.groupPriceKop)} / ${esc(o.unit)}</strong><span>${o.promoted?'<span class="ad-label">ПРОДВИГАЕТСЯ · ДЕМО</span>':status('collecting',PROC_STATES)}</span></div>`).join('')}</div>`}
function purchaseDrawer(){const p=purchase(selectedPurchase);if(!p)return '';const c=calculate(p,p.quantity),related=data.questions.filter(q=>q.purchaseId===p.id),contracts=data.contracts.filter(q=>q.purchaseId===p.id),other=Math.max(0,p.collectedQty-p.quantity);
return `<div class="scrim" data-action="closeDrawer"></div><section class="drawer" role="dialog" aria-modal="true" aria-label="Закупка ${esc(p.title)}"><div class="drawer-head"><div><span class="eyebrow">${esc(p.id)} / ЗАКУПКА</span><h2>${esc(p.title)}</h2></div><button class="icon-btn" data-action="closeDrawer" aria-label="Закрыть">${icon('x')}</button></div><div class="drawer-scroll"><div class="drawer-state">${status(p.status,PROC_STATES)}<span>Создана ${stamp(p.created)}</span></div><div class="drawer-description">${esc(p.description)}</div><div class="drawer-visual"><div class="drawer-visual-label">ВАША ЧАСТЬ ОБЩЕЙ ПАРТИИ</div><div class="drawer-volume"><strong>${num(p.quantity)}</strong><span>${esc(p.unit)}</span></div><div class="drawer-volume-context">из ${num(p.collectedQty)} ${esc(p.unit)} совместного объёма</div><div class="drawer-meter" role="progressbar" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${progress(p)}"><i style="width:${progress(p)}%"></i></div><div class="drawer-volume-foot"><span>Порог партии: ${num(p.thresholdQty)} ${esc(p.unit)}</span><strong>${progress(p)}%</strong></div></div>
 <div class="drawer-block"><span class="eyebrow">УСЛОВИЯ ЗАКУПКИ</span><dl class="drawer-facts"><div><dt>Поставщик</dt><dd>${esc(p.supplier)}</dd></div><div><dt>Ваше количество</dt><dd>${num(p.quantity)} ${esc(p.unit)}</dd></div><div><dt>Цена при общей партии</dt><dd>${money(c.groupKop)}</dd></div><div><dt>При отдельной закупке</dt><dd>${money(c.separateKop)}</dd></div><div><dt>Потенциальная экономия*</dt><dd class="saving">${money(c.savingKop)} · ${c.savingPct}%</dd></div><div><dt>Плановая доставка</dt><dd>${date(p.delivery)}</dd></div></dl></div>
 <div class="drawer-block"><span class="eyebrow">СВЯЗАННЫЕ РЕШЕНИЯ</span>${related.map(q=>`<button class="drawer-related" data-action="task" data-kind="question" data-id="${esc(q.id)}"><span>ВОПРОС</span>${esc(q.title)}${icon('arrow')}</button>`).join('')}${contracts.map(ct=>`<button class="drawer-related" data-action="task" data-kind="contract" data-id="${esc(ct.id)}"><span>КОНТРАКТ</span>${esc(ct.number)}${icon('arrow')}</button>`).join('')}${!related.length&&!contracts.length?'<p class="quiet">Пока нет связанных согласований или документов.</p>':''}</div></div><div class="drawer-footer"><small>* Демоданные. Условия действуют при достижении порога.</small><button class="btn primary" data-action="closeDrawer">Готово ${icon('check')}</button></div></section>`;
}
function dialogView(){if(selectedPurchase)return purchaseDrawer();if(!dialog)return '';
 let body='';
 if(dialog.kind==='confirmContract'){
  const c=data.contracts.find(x=>x.id===dialog.id);
  body=`<span class="eyebrow">ПОДТВЕРЖДЕНИЕ УСЛОВИЙ</span><h2>Проверьте решение</h2><p>Документ <b>${esc(c?.number)}</b>. Сумма условий: <b>${money(c?.amountKop||0)}</b>.</p>${infoBox('Это не электронная подпись','Действие фиксирует подтверждение в демоверсии. Юридически значимого подписания не происходит.')}
  <label class="consent"><input type="checkbox" id="confirm-ack"><span>Я ознакомился с демонстрационными условиями и понимаю, что это не юридическая подпись.</span></label><div class="modal-actions"><button class="btn outline" data-action="closeDialog">Отмена</button><button class="btn primary" disabled data-action="doConfirm" data-id="${esc(dialog.id)}" id="confirm-submit">Подтвердить в демо</button></div>`;
 }else if(dialog.kind==='declineContract'){
  const c=data.contracts.find(x=>x.id===dialog.id);body=`<span class="eyebrow">ОТКЛОНЕНИЕ ДОКУМЕНТА</span><h2>Отклонить условия?</h2><p>Документ <b>${esc(c?.number)}</b> будет помечен как отклонённый. Вы не сможете подтвердить его повторно в этой версии.</p><div class="modal-actions"><button class="btn outline" data-action="closeDialog">Вернуться</button><button class="btn danger" data-action="doDecline" data-id="${esc(dialog.id)}">Отклонить документ</button></div>`;
 }else if(dialog.kind==='reset'){
  body=`<span class="eyebrow">СБРОС ДЕМОНСТРАЦИИ</span><h2>Начать заново?</h2><p>Все ваши локальные демоответы, подтверждения, потребности и предложения поставщика вернутся к исходному состоянию.</p><div class="modal-actions"><button class="btn outline" data-action="closeDialog">Отмена</button><button class="btn danger" data-action="doReset">Сбросить</button></div>`;
 }else if(dialog.kind==='need'){
  body=`<span class="eyebrow">НОВАЯ ПОТРЕБНОСТЬ</span><h2>Добавить товар</h2><p>Укажите, что и к какому сроку требуется вашей компании.</p><form id="need-form" class="dialog-form"><label>Наименование<input required name="title" minlength="3" maxlength="110" placeholder="Например, питьевая вода 19 л" autofocus></label><div class="two-fields"><label>Количество<input required name="quantity" type="number" min="1" max="1000000" value="100"></label><label>Единица<select name="unit"><option value="шт.">шт.</option><option value="бут.">бут.</option><option value="пач.">пач.</option><option value="уп.">уп.</option><option value="рул.">рул.</option></select></label></div><label>Крайний срок<input required type="date" name="deadline" min="2026-10-17" value="2026-10-28"></label><div class="modal-actions"><button class="btn outline" type="button" data-action="closeDialog">Отмена</button><button class="btn primary" type="submit">Добавить потребность</button></div></form>`;
 }else if(dialog.kind==='newOffer'){
  body=`<span class="eyebrow">OPTIMA SUPPLY / ПУБЛИКАЦИЯ</span><h2>Новое предложение</h2><p>Цены указываются за одну единицу товара. Суммы в рублях.</p><form id="offer-form" class="dialog-form"><label>Наименование<input name="title" required minlength="3" maxlength="110" placeholder="Например, картонные коробки"></label><label>Категория<select name="category"><option>Для офиса</option><option>Упаковка</option><option>Канцелярия</option><option>Хозяйственные товары</option></select></label><label>Порог партии, шт.<input name="thresholdQty" type="number" required min="1" max="1000000" value="500"></label><div class="two-fields"><label>Розничная цена, ₽<input name="singlePriceRub" type="number" required min="0.01" step="0.01" value="150"></label><label>Оптовая цена, ₽<input name="groupPriceRub" type="number" required min="0.01" step="0.01" value="120"></label></div><div class="modal-actions"><button class="btn outline" type="button" data-action="closeDialog">Отмена</button><button class="btn primary" type="submit">Опубликовать (демо)</button></div></form>`;
 }
 return `<div class="dialog-backdrop" data-action="closeDialog"></div><div class="dialog-shell" role="dialog" aria-modal="true" aria-label="Действие"><button class="dialog-close icon-btn" data-action="closeDialog" aria-label="Закрыть">${icon('x')}</button>${body}</div>`;
}
function render(){if(!data)return;shell();if(selectedPurchase){root.insertAdjacentHTML('beforeend',purchaseDrawer());} if(dialog){document.querySelector('.dialog-shell input:not([type="checkbox"])')?.focus();} }
const $=s=>document.querySelector(s);
const targetAction=evt=>evt.target.closest('[data-action]');
root.addEventListener('click',async evt=>{
 const el=targetAction(evt);if(!el)return;
 const act=el.dataset.action,id=el.dataset.id;
 switch(act){
  case 'route':navigate(el.dataset.route);break;
  case 'showPurchase':selectedPurchase=id;render();break;
  case 'closeDrawer':selectedPurchase=null;render();break;
  case 'task':selectedPurchase=null;filter='all';if(el.dataset.kind==='question'){selectedQuestion=id;navigate('questions');selectedQuestion=id;render();}else{selectedContract=id;navigate('contracts');selectedContract=id;render();}break;
  case 'filter':filter=el.dataset.filter;selectedQuestion=null;selectedContract=null;render();break;
  case 'selectQuestion':selectedQuestion=id;render();break;
  case 'selectContract':selectedContract=id;render();break;
  case 'acceptQuestion':await mutate('answerQuestion',id,'accept');break;
  case 'declineQuestion':await mutate('answerQuestion',id,'decline');break;
  case 'confirmDialog':dialog={kind:'confirmContract',id};render();break;
  case 'declineDialog':dialog={kind:'declineContract',id};render();break;
  case 'closeDialog':dialog=null;render();break;
  case 'doConfirm':await mutate('confirmContract',id);break;
  case 'doDecline':await mutate('declineContract',id);break;
  case 'newNeed':dialog={kind:'need'};render();break;
  case 'deleteNeed':await mutate('deleteNeed',id);break;
  case 'newOffer':dialog={kind:'newOffer'};render();break;
  case 'resetDialog':dialog={kind:'reset'};render();break;
  case 'doReset':data=await api.reset();dialog=null;render();toast('Демонстрационные данные восстановлены');break;
  case 'promote':await mutate('promoteOffer',id);break;
  case 'notifications':showNotifs=!showNotifs;render();break;
  case 'readAll':await mutate('readNotifications','all');showNotifs=true;render();break;
  case 'openNotif':await mutate('readNotifications',id);navigate(el.dataset.target);break;
  case 'downloadPayments':downloadPayments();break;
 }
});
root.addEventListener('change',event=>{if(event.target.id==='confirm-ack'){const b=$('#confirm-submit');if(b)b.disabled=!event.target.checked;}});
root.addEventListener('input',event=>{if(event.target.id==='filter-search'){
 search=event.target.value;
 const focused=event.target, caret=focused.selectionStart;
 const set=data.purchases.filter(p=>filter==='all'||(filter==='active'?p.status!=='delivered':p.status==='delivered')).filter(p=>(p.title+' '+p.supplier+' '+p.id).toLowerCase().includes(search.toLowerCase()));
 const table=$('.purchase-table');if(table){table.innerHTML=`<div class="table-labels"><span>ЗАКУПКА</span><span>СТАТУС</span><span>ОБЩИЙ ОБЪЁМ</span><span>ВАШ ЗАКАЗ</span><span></span></div>${set.length?set.map(p=>purchaseRow(p)).join(''):'<div class="empty">Закупки не найдены.</div>'}`;}
 }});
root.addEventListener('submit',async event=>{
 const form=event.target;if(!['need-form','offer-form','settings-form'].includes(form.id))return;event.preventDefault();const values=Object.fromEntries(new FormData(form));
 if(form.id==='need-form')await mutate('createNeed',values);
 if(form.id==='offer-form')await mutate('createOffer',values);
 if(form.id==='settings-form')await mutate('updateSettings',values);
});
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&(dialog||selectedPurchase||showNotifs)){dialog=null;selectedPurchase=null;showNotifs=false;render();}});
addEventListener('hashchange',()=>{const next=location.hash.slice(1).split('?')[0];if(views.some(v=>v[0]===next)&&route!==next){route=next;filter='all';render();}});
function downloadPayments(){const lines=[['Код','Дата','Назначение','Сумма RUB','Статус'],...data.payments.map(p=>[p.reference,p.date,p.title,(p.sumKop/100).toFixed(2),paymentLabels[p.status][0]])];
 const csv='\uFEFF'+lines.map(cols=>cols.map(c=>`"${String(c).replaceAll('"','""')}"`).join(';')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='optima-demo-payments.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('CSV с демооперациями подготовлен');}
try{
 data=await api.getSnapshot();api.subscribe(snapshot=>{data=snapshot;render()});render();
}catch(e){root.innerHTML=`<div class="fatal-error"><h1>Не удалось загрузить кабинет</h1><p>${esc(e.message)}</p><button onclick="location.reload()">Повторить</button></div>`;}
